"""Actual normal title Continue; old H and A saves are generated by running the archived/current builds."""
from pathlib import Path
from urllib.parse import urlsplit
import base64,json,sys
from guard import P,need,fact,save
from playwright.sync_api import sync_playwright
D=Path(__file__).resolve().parent
O=json.loads((D/'observer.json').read_bytes())
U={'A':'http://127.0.0.1:18881/','B':'http://127.0.0.1:18882/','H':'http://127.0.0.1:18883/','S':'http://127.0.0.1:18884/'}
KEY='honro-first-act-profile-1'
COMMON=r"""
 const ids=['approved32:coastal-foundation','act4-handoff:32:body-joined'];
 const lists=b=>[b.honroLandmarks,b.honroElements,b.honroEnvironment?.placements];
 const places=b=>lists(b).flatMap(xs=>(xs||[]).filter(x=>ids.includes(x.assetId)));
 const valid=b=>Boolean(b&&b.mode==='campaign'&&b.honroStage===32&&b.stage===32&&
  b.honroCanonical===true&&b.honroCustom===false&&b.honroMapOrigin==='campaign'&&b.honroAct4Official===1);
 const sig=a=>{const s=JSON.stringify(a);let h=2166136261;for(let i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),16777619);return s.length+':'+(h>>>0).toString(16)};
 const state=b=>({terrain:JSON.stringify([b.terrain,b.honroWorldTerrain,b.honroPlayBounds,b.honroTerrainBounds]),
  units:JSON.stringify(b.units),objectives:JSON.stringify([b.honroObjectives,b.objectives,b.honroQuestTargets,b.honroGoalState,b.honroEncounterState]),
  phase:b.phase,round:b.round,revision:b.honroCampaignMapRevision,
  places:places(b).map(({asset,...x})=>x)});
 const rows=(b,fn)=>Object.fromEntries(ids.map(k=>[k,places(b).filter(x=>x.assetId===k).map(fn)]));
"""
PERSIST='key=>{'+COMMON+r"""
 const a=HonroApp;if(!valid(a.engine?.b)||a.profileStore.locked||a.screen!=='battle'||typeof a.flushBattleSave!=='function')throw Error('genuine legal app checkpoint unavailable');
 const previous=localStorage.getItem(key);
 a.dirty=true;a.flushBattleSave();
 const text=localStorage.getItem(key),p=JSON.parse(text),b=p.honroBattle;
 if(a.dirty||!text||!valid(b)||HonroCampaignMapRevision.obsolete(b)||JSON.stringify(state(b))!==JSON.stringify(state(a.engine.b)))
   throw Error('normal battle save did not contain the exact live checkpoint');
 if(places(b).some(x=>x.asset.honroStaticAssetRef!==1||x.asset.id!==x.assetId))throw Error('a signed role was not compacted by the real app');
 return {text,refs:rows(b,x=>x.asset.signature),state:state(b),samePriorBytes:text===previous,issuer:'HonroApp.flushBattleSave'};
}"""
RESTORED='()=>{'+COMMON+r"""
 const a=HonroApp,b=a.engine?.b;if(!valid(b)||a.profileStore.locked)throw Error('actual Continue did not mount a valid campaign battle');
 const out=Object.fromEntries(ids.map(k=>[k,HONRO_PROJECT.library.filter(x=>x.id===k).map(sig)]));
 return {state:state(b),active:out,mounted:rows(b,x=>sig(x.asset))};
}"""
NEG='text=>{'+COMMON+r"""
 const saved=JSON.parse(text).honroBattle;
 const test=f=>{const b=structuredClone(saved);f(b);const old=JSON.stringify(b);
  return !HonroProfileStore.restoreBattleArt(b)&&JSON.stringify(b)===old};
 const role=(b,n)=>places(b).find(x=>x.assetId===ids[n]);
 return {wrongStage:test(b=>b.honroStage=33),wrongMode:test(b=>b.mode='practice'),
  workshop:test(b=>b.honroMapOrigin='workshop'),custom:test(b=>b.honroCustom=true),
  nonOfficial:test(b=>b.honroAct4Official=0),badFoundation:test(b=>role(b,0).asset.signature='1:deadc0de'),
  badJoined:test(b=>role(b,1).asset.signature='3:badbad'),badSecondAtomic:test(b=>places(b).at(-1).asset.honroStaticAssetRef=2)};
}"""
# Historical executable + exact stock original art; placements marked QA-only,
# deliberately constructed to reach a currently unplaced canonical legacy family.
LEGACY_MINT='arg=>{'+COMMON+r'''
 const a=HonroApp,b=a.engine?.b,lib=HONRO_PROJECT.library,legacyIds=Object.keys(arg.refs);
 if(!valid(b)||a.profileStore.locked||a.screen!=='battle')throw Error('wrong legacy QA issuer');
 const old=b.honroLandmarks, placement=old.find(p=>p.id==='approved32-body'&&p.asset?.id==='act4-handoff:32:body-joined');
 if(!placement)throw Error('normal official issuer placement missing');
 try{
  const scoped=legacyIds.map(id=>{
   const matches=lib.filter(x=>x.id===id),asset=matches[0];
   if(matches.length!==1||!asset.vector||asset.collision?.length||asset.interactionType||sig(asset)!==arg.refs[id])throw Error('exact historical archive identity absent: '+id);
   return {...placement,id:'qa-existing-prior-art:'+id,assetId:id,opacity:0,nativeTerrainIds:[],collisionIds:[],asset};
  });
  b.honroLandmarks=[...old,...scoped];
  a.dirty=true;a.flushBattleSave();
  const text=localStorage.getItem(arg.key), saved=JSON.parse(text).honroBattle;
  if(a.dirty||!valid(saved)||HonroCampaignMapRevision.obsolete(saved)||JSON.stringify(state(saved))!==JSON.stringify(state(b)))throw Error('actual historic fixture not persisted');
  const scopedRows=saved.honroLandmarks.filter(x=>x.id.startsWith('qa-existing-prior-art:'));
  return {text,state:state(saved),refs:Object.fromEntries(scopedRows.map(x=>[x.asset.id,x.asset.signature]))};
 }finally{b.honroLandmarks=old;}
}'''
NEEDS='()=>{const app=HonroApp,b=app.profile.honroBattle;const store=HonroProfileStore;return {archiveNeeded:!!store.needsLegacy32Art(b),hasBattleArt:!!HonroCampaignLoader.hasBattleArt(b)};}'
LEGACY_READ='arg=>{'+COMMON+r'''
 const a=HonroApp,b=a.engine.b,lib=HONRO_PROJECT.library,legacyIds=Object.keys(arg.refs);
 if(!valid(b)||legacyIds.some(id=>lib.some(x=>x.id===id)||lib.filter(x=>x.id==='act4compat32:v1:'+id).length!==1))throw Error('legacy provider polluted ordinary library');
 const scopedRows=b.honroLandmarks.filter(x=>x.id.startsWith('qa-existing-prior-art:'));
 if(scopedRows.length!==legacyIds.length||scopedRows.some(x=>x.opacity!==0||!x.asset.vector||x.asset.collision?.length||x.assetId!==x.asset.id||sig(x.asset)!==arg.refs[x.asset.id]))throw Error('exact hidden historical fixture failed to restore');
 a.dirty=true;a.flushBattleSave();
 const text=localStorage.getItem(arg.key), saved=JSON.parse(text).honroBattle;
 const scoped=saved.honroLandmarks.filter(x=>x.id.startsWith('qa-existing-prior-art:'));
 const refs=Object.fromEntries(scoped.map(x=>[x.asset.id,x.asset.signature]));
 if(a.dirty||scoped.length!==legacyIds.length||scoped.some(x=>x.asset.honroStaticAssetRef!==1)||legacyIds.some(id=>refs[id]!==arg.refs[id]))throw Error('actual resave did not preserve exact archived asset IDs');
 return {refs,state:state(saved)};
}'''
LEGACY_NEG='()=>{const S=HonroProfileStore, old=HonroApp.profile.honroBattle, t=x=>!S.needsLegacy32Art(x)&&!S.restoreBattleArt(structuredClone(x));const bad=structuredClone(old);for(const x of bad.honroLandmarks.filter(y=>y.id.startsWith("qa-existing-prior-art:")))x.asset.signature="1:bad";return {badSignature:t(bad),wrongStage:t({...old,honroStage:31}),workshop:t({...old,honroMapOrigin:"workshop"}),custom:t({...old,honroCustom:true}),notOfficial:t({...old,honroAct4Official:0})};}'
def main(w):
 q={'status':'HOLD','scope':'Real archived/current/candidate app saves in fresh anonymous contexts. Synthetic QA slots only, exact owner F/B; no save exported.','devices':{}}
 rr=json.loads((w/'OUT'/'stage32'/'NATIVE-ROUTES.json').read_bytes())['routes']
 def report():save(w,'RESUME.json',q)
 report()
 with sync_playwright()as pw:
  ch=pw.chromium.launch(headless=True);q['browser']=ch.version
  need(ch.version=='151.0.7922.34','actual Chromium version')
  def opened(arm,d,old=None):
   u=U[arm];c=ch.new_context(viewport=dict(zip(('width','height'),d['dims'])),device_scale_factor=1,service_workers='block')
   need(c.storage_state()=={'cookies':[],'origins':[]},'fresh anonymized test context required')
   c.add_init_script('('+O['INIT']+')();'+O['INIT_SEED'])
   if old is not None:
    o=urlsplit(u);path=o.path+'HONRO.html';origin=f'{o.scheme}://{o.netloc}'
    need((origin,path) in [('http://127.0.0.1:18881','/HONRO.html'),('http://127.0.0.1:18882','/HONRO.html'),('http://127.0.0.1:18883','/HONRO.html')],'unknown test boot origin')
    c.add_init_script('if(location.origin==='+json.dumps(origin)+'&&location.pathname==='+json.dumps(path)+'){localStorage.setItem('+json.dumps(KEY)+','+json.dumps(old)+');}')
   p=c.new_page();net={};err=[];legacy=[]
   lazy=u+P['lazy']['directPath'];watch={u+k for k in rr[arm]}|{lazy}
   p.on('response',lambda h:net.setdefault(h.url,h) if h.url in watch else None)
   p.on('request',lambda h:legacy.append(h.url) if h.url==lazy else None)
   p.on('pageerror',lambda v:err.append(str(v)))
   nav=p.goto(u+'HONRO.html',wait_until='domcontentloaded',timeout=50000)
   need(nav and nav.status==200 and nav.url==u+'HONRO.html' and not nav.from_service_worker,'normal boot required')
   p.wait_for_function("()=>document.documentElement.dataset.honroReady==='true'&&typeof HonroCampaignLoader?.ensureStage==='function'",timeout=90000)
   p.evaluate("()=>{__honroResetDiagnosticSeed();HonroApp.audio?.configure?.({...HonroApp.profile.settings,music:false,sound:false});}")
   return c,p,net,err,legacy
  def ready(p):
   p.wait_for_function("()=>HonroApp.engine?.b?.honroStage===32&&!HonroApp.profileStore.locked",timeout=22000)
  def routes(arm,net):
   out={}
   for k,pin in rr[arm].items():
    z=net.get(U[arm]+k)
    need(z and z.status==200 and not z.from_service_worker and fact(z.body())==pin,('real HTTP resume bytes',arm,k))
    out[k]=pin
   return out
  def archive(arm,net,seen,expected):
   p=P['lazy']['directPath'];u=U[arm]+p
   ans={'requests':len(seen),'path':p}
   need(seen==([u]if expected else []),('actual Stage32 lazy route count differs',arm,seen,expected))
   if expected:
    x=net.get(u)
    need(x and x.status==200 and not x.from_service_worker and fact(x.body())==P['lazy']['legacyDirectRetained'],'unmodified exact lazy HTTP archive required')
    ans['body']=P['lazy']['legacyDirectRetained']
   return ans
  def shot(p,d,case):
   a={'id':32,'mapId':'stage-32','name':'south','dx':0,'dy':1,'readback':False,'fixedNow':O['PHASE']}
   meta=p.evaluate(O['FROZEN'],a)['meta'];p.evaluate(O['DECODE']);p.evaluate(O['FROZEN'],{**a,'readback':True})
   from capture import same_nums
   need(same_nums({k:meta[k]for k in ('actual','viewport','backing')},{k:d[k]for k in ('actual','viewport','backing')}),'resume camera differs')
   x=base64.b64decode(p.evaluate(O['CANVAS']),validate=True);f=d['device']+'-resume-'+case+'.png'
   (w/'OUT'/'stage32'/f).write_bytes(x)
   return {'path':f,**fact(x)}
  rows=P['rows']
  expected={'H':{k:v['previous']for k,v in rows.items()},'A':{k:v.get('previousOptimized',v['previous'])for k,v in rows.items()},
            'B':{k:v['current']for k,v in rows.items()}}
  try:
   for d in (x for x in P['devs'] if x['name']=='south'):
    log=q['devices'][d['device']]={};setup={}
    for arm in ('H','A','B'):
     c=None
     try:
      c,p,net,err,legacy=opened(arm,d)
      p.evaluate(O['LAUNCH'],32);ready(p)
      s=p.evaluate(PERSIST,KEY)
      log['generate-'+arm]={'actualTokenRefs':s['refs'],'saved':fact(s['text'].encode()),'issuer':s['issuer'],'samePriorBytes':s['samePriorBytes'],'HTTP':routes(arm,net),'lazyArchive':archive(arm,net,legacy,False)};report()
      need(not err and all(s['refs'][k] and all(x==sig for x in s['refs'][k])for k,sig in expected[arm].items()),
       ('actual emitted stock/approved token does not match, no substitution',arm,s['refs']))
      setup[arm]=s
     except Exception as e:
      log.setdefault('generate-'+arm,{})['error']=repr(e);print(d['device'],arm,repr(e),flush=True);report()
     finally:
      if c:c.close()
    for arm,src in [('H','H'),('A','A'),('A','H'),('B','H'),('B','A'),('B','B')]:
     case=src+'-to-'+arm
     if src not in setup:
      log[case]={'error':'required exact browser-generated save missing'};report();continue
     s=setup[src];c=None
     try:
      c,p,net,err,legacy=opened(arm,d,s['text'])
      need(p.evaluate("()=>!HonroApp.engine&&Boolean(HonroApp.profile.honroBattle)"),'cold checkpoint not available')
      copied=p.evaluate("k=>localStorage.getItem(k)",KEY)
      need(copied==s['text'],'normal cold boot did not read exact serialized snapshot')
      if arm in ('A','B'):
       need(p.evaluate(NEEDS)['archiveNeeded'] is False,'genuine natural H/A/B references incorrectly classified as dormant archive')
      p.evaluate("()=>{HonroApp.frame=()=>{};HonroApp.continue();}");ready(p)
      z=p.evaluate(RESTORED)
      need(z['state']==s['state'] and all(z['active'][k]==[v] and z['mounted'][k] and all(x==v for x in z['mounted'][k])for k,v in expected[arm].items()),
           'restored real stage state, terrain, objects, or provider drift')
      v={'physicalAndStateExact':True,'mounts':z['mounted'],'HTTP':routes(arm,net),'raw':shot(p,d,case),'lazyArchive':archive(arm,net,legacy,False),'exactImportedSave':fact(copied.encode())}
      if arm=='B' and src in ('A','H'):
       v['negatives']=p.evaluate(NEG,s['text'])
       need(len(v['negatives'])==8 and all(v['negatives'].values()),'accepted unrelated signature or stage')
      need(not err,('unexpected normal runtime errors',err))
      log[case]=v;report()
     except Exception as e:
      log[case]={'error':repr(e)};print(d['device'],case,repr(e),flush=True);report()
     finally:
      if c:c.close()
    c=None; minted=None
    try:
     c,p,net,err,legacy=opened('S',d)
     p.evaluate(O['LAUNCH'],32);ready(p)
     arg={'refs':P['nativeArchiveFixtureStock']['compatRefs'],'key':KEY}
     v=p.evaluate(LEGACY_MINT,arg)
     need(v['refs']==arg['refs'] and not err,'the QA issuer did not save exact 3 legacy refs')
     minted=v
     log['fixture-S-minted']={'issuer':'72dd native flushBattleSave; explicitly posed QA canonical legacy placements, not naturally occurring H/player save',
        'refs':v['refs'],'saved':fact(v['text'].encode()),'HTTP':routes('S',net),'lazyArchive':archive('S',net,legacy,False)};report()
    except Exception as e:
     log['fixture-S-minted']={'error':repr(e)};print(d['device'],'fixture-source',repr(e),flush=True);report()
    finally:
     if c:c.close()
    for arm in ('A','B'):
     c=None;case='fixture-S-to-'+arm
     if minted is None:
      log[case]={'error':'missing exact old archive QA save'};report();continue
     try:
      c,p,net,err,legacy=opened(arm,d,minted['text'])
      copied=p.evaluate("k=>localStorage.getItem(k)",KEY)
      need(copied==minted['text'] and p.evaluate(NEEDS)=={'archiveNeeded':True,'hasBattleArt':False} and not legacy,'genuine cold test did not start with exact missing archive fixture')
      before=p.evaluate(LEGACY_NEG)
      need(len(before)==5 and all(before.values()) and not legacy,'scope negatives before lazy fetch')
      p.evaluate("()=>{HonroApp.frame=()=>{};HonroApp.continue();}");ready(p)
      z=p.evaluate(RESTORED)
      need(z['state']==minted['state'] and all(z['active'][k]==[v] and z['mounted'][k] and all(x==v for x in z['mounted'][k])for k,v in expected[arm].items()),'true archive QA restore changed normal stage state/approved artwork')
      oldR=p.evaluate(LEGACY_READ,arg)
      need(oldR['refs']==arg['refs'] and oldR['state']==minted['state'],'archive QA native resave corrupted original IDs/state')
      after=p.evaluate(LEGACY_NEG)
      need(after==before and not err,'scope negatives after lazy fetch')
      qrow={'fixtureOnly':True,'physicalAndStateExact':True,'importedSave':fact(copied.encode()),'archive':archive(arm,net,legacy,True),
       'archiveMountedAndResavedRefs':oldR['refs'],'normalMounted':z['mounted'],'negativeBefore':before,'negativeAfter':after,'HTTP':routes(arm,net)}
      log[case]=qrow;report()
     except Exception as e:
      log[case]={'error':repr(e)};print(d['device'],case,repr(e),flush=True);report()
     finally:
      if c:c.close()
  finally:ch.close()
 need(set(q['devices'])=={'PC','Mobile'} and all(len(d)==12 and not any('error'in v for v in d.values()) for d in q['devices'].values()),'one or more actual stock/candidate historical verification cases HOLD')
 q['status']='PASS_ACTUAL_STAGE32_R10_ARCHIVED_CURRENT_AND_NEW_COLD_RESUME_PC_M_NO_DEPLOY';report()
if __name__=='__main__':main(Path(sys.argv[1]))
